def summarize(lines, *, casefold=False, min_count=0):
    if isinstance(min_count, bool) or not isinstance(min_count, int) or min_count < 0:
        raise ValueError("min_count must be a nonnegative integer")
    totals = {}
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if ":" not in stripped:
            raise ValueError("malformed record")
        name, count_text = stripped.split(":", 1)
        name = name.strip()
        count_text = count_text.strip()
        if not name:
            raise ValueError("empty name")
        try:
            count = int(count_text)
        except ValueError as exc:
            raise ValueError("invalid count") from exc
        if count < 0:
            raise ValueError("negative count")
        key = name.casefold() if casefold else name
        totals[key] = totals.get(key, 0) + count
    if min_count == 0:
        return totals
    return {name: total for name, total in totals.items() if total >= min_count}

import unittest
from ledger import summarize
class Exclude(unittest.TestCase):
 def test_one_name(self):self.assertEqual(summarize(["a:3","b:5"],exclude=("a",)),{"b":5})
 def test_folded(self):self.assertEqual(summarize(["Straße:4","oak:2"],casefold=True,exclude=(" STRASSE ",)),{"oak":2})
 def test_exact_case(self):self.assertEqual(summarize(["A:1","a:2"],exclude=("A",)),{"a":2})
 def test_iterator_and_threshold(self):self.assertEqual(summarize(iter(["a:2","b:7","c:1"]),exclude=iter(["b"]),min_count=2),{"a":2})
 def test_invalid_not_hidden(self):
  with self.assertRaises(ValueError):summarize(["a:-1"],exclude=("a",))

import unittest
from ledger import summarize
class LedgerTests(unittest.TestCase):
 def test_repeated_names_add(self):
  self.assertEqual(summarize(["oak:2","oak:3","ash:0"]),{"oak":5,"ash":0})
 def test_trim(self):
  self.assertEqual(summarize(["  oak : 2  "]),{"oak":2})
 def test_comments_and_empty(self):
  self.assertEqual(summarize(["","  "," # note","ash:1"]),{"ash":1})
 def test_unicode_name(self):
  self.assertEqual(summarize(["café:4","café:1"]),{"café":5})
 def test_empty_input(self):
  self.assertEqual(summarize([]),{})
 def test_negative_count(self):
  with self.assertRaises(ValueError):summarize(["oak:-1"])
 def test_empty_name(self):
  with self.assertRaises(ValueError):summarize([":1"])
 def test_malformed(self):
  for row in ["oops","a:x","a:1:2"]:
   with self.subTest(row=row),self.assertRaises(ValueError):summarize([row])

import unittest
from ledger import summarize
class Casefold(unittest.TestCase):
 def test_default_preserves_names(self):
  self.assertEqual(summarize(["Oak:2","oak:3"]),{"Oak":2,"oak":3})
 def test_ascii_merge(self):
  self.assertEqual(summarize([" Oak :2","oak:3"],casefold=True),{"oak":5})
 def test_unicode_expansion(self):
  self.assertEqual(summarize(["Straße:2","STRASSE:4"],casefold=True),{"strasse":6})
 def test_iterator_and_comments(self):
  self.assertEqual(summarize(iter(["# comment",""," Σ :1","ς:3"]),casefold=True),{"σ":4})
 def test_invalid_still_rejected(self):
  with self.assertRaises(ValueError):summarize(["oak:-1"],casefold=True)

import unittest
from ledger import summarize
class Threshold(unittest.TestCase):
 def test_default_keeps_zero(self):
  self.assertEqual(summarize(["oak:0"]),{"oak":0})
 def test_filters_low_totals(self):
  self.assertEqual(summarize(["oak:2","elm:7"],min_count=4),{"elm":7})
 def test_applies_after_aggregation(self):
  self.assertEqual(summarize(["oak:2","oak:3"],min_count=4),{"oak":5})
 def test_exact_boundary(self):
  self.assertEqual(summarize(["oak:4"],min_count=4),{"oak":4})
 def test_fold_before_threshold(self):
  self.assertEqual(summarize(["Straße:2","STRASSE:3"],casefold=True,min_count=4),{"strasse":5})
 def test_reject_invalid_thresholds_even_empty(self):
  for value in [-1,True,False,1.2,"2",None]:
   with self.subTest(value=value),self.assertRaises(ValueError):summarize([],min_count=value)
 def test_iterator_single_pass(self):
  self.assertEqual(summarize(iter(["a:2","a:3","b:1"]),min_count=3),{"a":5})
 def test_record_validation_not_bypassed(self):
  with self.assertRaises(ValueError):summarize(["a:-1"],min_count=99)

def summarize(lines, *, casefold=False, min_count=0, exclude=()):
    if isinstance(min_count, bool) or not isinstance(min_count, int) or min_count < 0:
        raise ValueError("min_count must be a nonnegative integer")
    excluded = set()
    for name in exclude:
        stripped = name.strip()
        if casefold:
            stripped = stripped.casefold()
        excluded.add(stripped)
    totals = {}
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if ":" not in stripped:
            raise ValueError("malformed record")
        name, count_text = stripped.split(":", 1)
        name = name.strip()
        count_text = count_text.strip()
        if not name:
            raise ValueError("empty name")
        try:
            count = int(count_text)
        except ValueError as exc:
            raise ValueError("invalid count") from exc
        if count < 0:
            raise ValueError("negative count")
        key = name.casefold() if casefold else name
        totals[key] = totals.get(key, 0) + count
    result = totals
    if excluded:
        result = {name: total for name, total in result.items() if name not in excluded}
    if min_count == 0:
        return result
    return {name: total for name, total in result.items() if total >= min_count}
